FOUNDER = {"acme"}


def said(who: str, body: str) -> dict:
    return {"user": {"login": who}, "body": body, "created_at": "2026-11-23T12:00:00Z"}


def test_revise_then_resubmit_goes_back_to_waiting_never_further():
    revise = said("acme", "/revise make it a monthly plan")
    assert approval.decide([revise], FOUNDER) == {"state": "revision", "kind": "", "note": "make it a monthly plan"}
    back = said("acme-bot", approval.RESUBMITTED + "\n**Resubmitted**\n\n> /approve")
    assert approval.decide([revise, back], FOUNDER)["state"] == "waiting", "a quoted /approve never counts"
    assert approval.decide([back], FOUNDER)["state"] == "waiting", "a resubmit with no /revise changes nothing"
    assert approval.decide([revise, back, said("acme", "/approve")], FOUNDER)["state"] == "approved"
    assert approval.decide([revise, said("mallory", "/approve")], FOUNDER)["state"] == "revision"


