def test_resubmit_and_expire_through_the_commands(root, fake, capsys):
    req = fake.make("[approval] Deploy", "**Scope:** this action only", [approval.LABEL, "gate:deploy"])
    old = fake.make("[approval] Old", "", [approval.LABEL, "gate:deploy"])
    fake.issues[old]["created_at"] = "2026-01-01T00:00:00Z"
    fake.issues[req]["created_at"] = "2099-01-01T00:00:00Z"
    args = ["--root", str(root)]
    assert approval.main(["resubmit", str(req), "--note", "x", *args]) == approval.NO, "nothing to resubmit yet"
    fake.comments[req].append(said("acme", "/revise smaller"))
    assert approval.main(["check", "deploy", "--issue", str(req), *args]) == approval.REVISE
    assert "smaller" in capsys.readouterr().out
    assert approval.main(["resubmit", str(req), "--note", "now smaller", *args]) == approval.WAITING
    assert approval.main(["check", "deploy", "--issue", str(req), *args]) == approval.WAITING
    assert approval.main(["expire", *args]) == approval.APPROVED
    assert fake.issues[old]["state"] == "closed" and fake.issues[req]["state"] == "open"
    assert "not approved" in fake.comments[old][-1]["body"]


def test_pause_and_resume_come_only_from_the_founder():
    st = control.state([said("acme", "/pause engineer runaway costs"), said("mallory", "/resume engineer"),
                        said("acme", "/pause role:qa"), said("acme", "/resume qa")], FOUNDER)
    assert st == {"all": None, "roles": {"engineer": "runaway costs"}}
    assert control.paused(st, "engineer") == "runaway costs" and control.paused(st, "qa") is None
    st = control.state([said("acme", "/pause all holiday"), said("acme", "/resume growth")], FOUNDER)
    assert control.paused(st, "growth") == "holiday", "resuming one role doesn't lift a pause on all"
    assert control.paused(control.state([said("acme", "/pause all"), said("acme", "/resume all")], FOUNDER), "qa") is None


def test_a_paused_role_never_starts(root, fake, capsys):
    from test_heartbeat import ticket
    ticket(fake, "engineer")
    issue = fake.make(control.TITLE, control.BODY, [control.LABEL])
    fake.comments[issue].append(said("acme", "/pause engineer checking the bill"))
    run = lambda *a: heartbeat.main([*a, "--root", str(root), "--month", MONTH])  # noqa: E731
    assert run("start", "engineer", "--now", str(NOW)) == heartbeat.STOP
    assert "paused by the founder (checking the bill)" in capsys.readouterr().out
    assert not any(r.startswith("refs/") for r in fake.refs), "no lock, no claim"
    fake.comments[issue].append(said("acme", "/resume engineer"))
    assert run("start", "engineer", "--now", str(NOW)) == heartbeat.OK


def test_sub_tickets_wait_for_an_approved_plan_and_a_changed_plan_asks_again(root, fake, capsys):
    from test_tickets import ticket
    run = lambda *a: tickets.main([*a, "--root", str(root)])  # noqa: E731
    parent = ticket(fake, "product", "Invoicing")
    a, b = ticket(fake, "engineer", "API", parent=parent), ticket(fake, "engineer", "UI", parent=parent)
    assert run("claim", str(a), "--role", "engineer") == tickets.REFUSED
    assert "plan isn't approved yet" in capsys.readouterr().out
    assert run("plan", str(parent), "--by", "product", "--note", "API first") == tickets.OK
    plans = lambda: [n for n in fake.issues if "gate:plan" in fake.names(n)]  # noqa: E731
    req = max(plans())
    assert f"**Sub-tickets:** #{a}, #{b}" in fake.issues[req]["body"] and "gate:plan" in fake.names(req)
    assert run("claim", str(a), "--role", "engineer") == tickets.REFUSED, "waiting"
    fake.comments[req].append(said("acme", "/approve"))
    assert run("claim", str(a), "--role", "engineer") == tickets.OK
    c = ticket(fake, "engineer", "Exports", parent=parent)
    assert run("claim", str(c), "--role", "engineer") == tickets.REFUSED
    assert "isn't in" in capsys.readouterr().out
    assert run("plan", str(parent), "--by", "product") == tickets.OK
    assert "revision after" in fake.issues[max(plans())]["body"]
    assert run("claim", str(b), "--role", "engineer") == tickets.REFUSED, "the newest plan decides, and it waits"
    assert run("claim", str(parent), "--role", "product") == tickets.OK, "a ticket with no parent never waits"
    assert REPO


def test_a_wake_comes_only_from_the_founder_and_never_touches_a_pause():
    st = control.state([said("acme", "/pause qa"), said("acme", "/wake qa"), said("acme", "/wake all")], FOUNDER)
    assert control.paused(st, "qa") == "paused", "a wake never lifts a pause"
    got = control.wakes([said("acme", "/wake role:engineer"), said("mallory", "/wake qa")], FOUNDER)
    assert got == {"engineer": "2026-11-23T12:00:00Z"}


def test_a_wake_lasts_until_a_run_of_that_role_ends_or_it_goes_stale():
    import datetime as dt
    now = dt.datetime(2026, 11, 23, 12, 30, tzinfo=dt.timezone.utc)
    st = {"wakes": {"engineer": "2026-11-23T12:00:00Z", "all": "2026-11-23T09:00:00Z"}}
    assert control.woken(st, "engineer", [], now) == "2026-11-23T12:00:00Z"
    assert control.woken(st, "engineer", [{"role": "qa", "at": "2026-11-23T12:20:00Z"}], now)
    assert not control.woken(st, "engineer", [{"role": "engineer", "at": "2026-11-23T12:20:00Z"}], now), "spent"
    assert control.woken(st, "engineer", [{"role": "engineer", "at": "2026-11-23T11:50:00Z"}], now), "an older run"
    assert not control.woken(st, "qa", [], now), "/wake all three and a half hours ago is stale"
    assert not control.woken({"wakes": {}}, "qa", [], now) and not control.woken({}, "qa", [], now)
